#include <iostream>
#include <string>

using namespace std;

int mask(int x) {
    int result = 0;
    for (char c : to_string(x)) {
        if (c == '4' || c == '7')
            result = result * 10 + (c - '0');
    }
    return result;
}

int main() {
    int a, b;
    cin >> a >> b;

    ++a;
    while (mask(a) != b)
        ++a;

    cout << a;
    return 0;
}

